begin;
set local app.auvo_sync_write='true';
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(9);
select has_function('pcm','sso_salvar_linhas_materiais_mediada',array['uuid','uuid','integer','jsonb'],'edição mediada existe');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values ('17993000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s179-editar@test.local',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17993000-0000-4000-8000-000000000001','superadmin','Gestor sintético',true);
insert into pcm.clientes(id,nome,created_by) values ('17993000-0000-4000-8000-000000000002','Cliente A','17993000-0000-4000-8000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17993000-0000-4000-8000-000000000001','material.gerir','17993000-0000-4000-8000-000000000002');
insert into pcm.ordens_servico(id,client_id,numero,titulo,categoria,created_by) values ('17993000-0000-4000-8000-000000000011','17993000-0000-4000-8000-000000000002','S179-ED-A','OS A','corretiva','17993000-0000-4000-8000-000000000001');
insert into pcm.listas_materiais(id,cliente_id,ordem_servico_id,responsavel,texto_original,criado_por) values ('17993000-0000-4000-8000-000000000021','17993000-0000-4000-8000-000000000002','17993000-0000-4000-8000-000000000011','cliente','Material A','17993000-0000-4000-8000-000000000001');
set local request.jwt.claims='{"sub":"17993000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}';
set local role authenticated;
select throws_ok($$select pcm.sso_salvar_linhas_materiais_mediada('17993000-0000-4000-8000-000000000031','17993000-0000-4000-8000-000000000021',1,'[{"descricao":"Material A","quantidade":null,"unidade":null,"trechosOriginais":["Material A"]}]')$$,'55000','edicao_materiais_bloqueada','gate fechado impede edição');
reset role;
update pcm.sso_edicao_materiais_mediada_gate set habilitado=true where id;
set local role authenticated;
select lives_ok($$select pcm.sso_salvar_linhas_materiais_mediada('17993000-0000-4000-8000-000000000031','17993000-0000-4000-8000-000000000021',1,'[{"descricao":"Material A","quantidade":null,"unidade":null,"trechosOriginais":["Material A"]}]')$$,'salva linhas autorizadas');
select lives_ok($$select pcm.sso_salvar_linhas_materiais_mediada('17993000-0000-4000-8000-000000000031','17993000-0000-4000-8000-000000000021',1,'[{"descricao":"Material A","quantidade":null,"unidade":null,"trechosOriginais":["Material A"]}]')$$,'replay idêntico aceito');
select throws_ok($$select pcm.sso_salvar_linhas_materiais_mediada('17993000-0000-4000-8000-000000000032','17993000-0000-4000-8000-000000000021',1,'[]')$$,'40001','revisao_obsoleta','revisão obsoleta recusada');
select throws_ok($$select pcm.sso_salvar_linhas_materiais_mediada('17993000-0000-4000-8000-000000000033','17993000-0000-4000-8000-000000000021',2,'[{"descricao":"Outro","quantidade":null,"unidade":null,"trechosOriginais":["Inventado"]}]')$$,'22023','evidencia_invalida','trecho inexistente recusado');
reset role;
select is((select texto_original from pcm.listas_materiais where id='17993000-0000-4000-8000-000000000021'),'Material A','texto original preservado');
select is((select count(*)::integer from pcm.sso_lista_materiais_versoes where lista_id='17993000-0000-4000-8000-000000000021'),1,'replay não duplica versão');
select ok(has_function_privilege('authenticated','pcm.sso_salvar_linhas_materiais_mediada(uuid,uuid,integer,jsonb)','execute') and not has_function_privilege('authenticated','pcm.sso_salvar_linhas_materiais(uuid,uuid,integer,jsonb)','execute') and not has_function_privilege('anon','pcm.sso_salvar_linhas_materiais_mediada(uuid,uuid,integer,jsonb)','execute'),'mediadora autenticada e núcleo privado');
select * from finish();
rollback;
